package demux

import (
	"testing"

	"github.com/abema/go-mp4"

	"archive/internal/clock"
)

// writeFrag builds a tiny two-track fMP4 via the remux writer is not
// importable here (import cycle), so this test relies on the fixture
// generated by package fixture in an integration test. This file only
// exercises helpers that need no container bytes.
func TestDecodeLang(t *testing.T) {
	// "eng" packed as five-bit values (c - 0x60).
	packed := [3]byte{'e' - 0x60, 'n' - 0x60, 'g' - 0x60}
	if got := decodeLang(packed); got != "eng" {
		t.Fatalf("decodeLang = %q", got)
	}
	if got := decodeLang([3]byte{0, 0, 0}); got != "" {
		t.Fatalf("undefined language should be empty, got %q", got)
	}
}

func TestBoxBytesBounds(t *testing.T) {
	data := []byte{0, 0, 0, 8, 'f', 't', 'y', 'p'}
	got := boxBytes(data, boxInfoStub(0, 8))
	if string(got) != string(data) {
		t.Fatalf("boxBytes = %v", got)
	}
	if got := boxBytes(data, boxInfoStub(4, 8)); got != nil {
		t.Fatalf("out-of-range box must yield nil, got %v", got)
	}
}

func TestWrapPeriodGuard(t *testing.T) {
	for _, ts := range []uint32{90000, 48000} {
		_ = clock.WrapPeriod(ts)
	}
}

func boxInfoStub(off, size uint64) mp4.BoxInfo {
	return mp4.BoxInfo{Offset: off, Size: size, HeaderSize: 8}
}
